// The messages of the self-check machines: the part of SIP2 they speak, with each field written
// as a two-letter code and its value, ended by '|'. A checkout request is "11" followed by its
// fields; the reply is "12", then 1 when the item was lent or 0 when it was not, then its fields.
import { checkOutItem } from '../circulation/checkout.js';
import { findMemberByCard } from '../members/accounts.js';

/** Reads a checkout request: the member's card number (field AA) and the item's barcode (AB). */
export function parseCheckoutRequest(message) {
  if (!message.startsWith('11')) throw new Error('Not a checkout request');
  const fields = readFields(message.slice(2));
  return { cardNumber: fields.get('AA') ?? '', barcode: fields.get('AB') ?? '' };
}

/** Writes the reply to a checkout: the due date (AH) when the item was lent, else the reason (AF). */
export function formatCheckoutReply(result) {
  if (!result.ok) return `120|AF${result.reason}|`;
  return `121|AB${result.loan.itemId}|AH${result.loan.dueOn}|`;
}

/** Handles one checkout request from a self-check machine, and returns the reply to send it. */
export function handleCheckoutMessage(store, message, today) {
  const request = parseCheckoutRequest(message);
  const member = findMemberByCard(store, request.cardNumber);
  if (member === undefined) return formatCheckoutReply({ ok: false, reason: 'unknown-member' });
  return formatCheckoutReply(checkOutItem(store, { barcode: request.barcode, memberId: member.id, today }));
}

function readFields(text) {
  const fields = new Map();
  for (const field of text.split('|')) {
    if (field.length >= 2) fields.set(field.slice(0, 2), field.slice(2));
  }
  return fields;
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { handleCheckoutMessage, parseCheckoutRequest } from '../lib/legacy/sip2.js';
import { ADA, BOOK, sampleStore, TODAY } from './sample-library.js';

test('reads the card number and the barcode of a checkout request', () => {
  assert.deepEqual(parseCheckoutRequest(`11|AA${ADA.cardNumber}|AB${BOOK.barcode}|`), {
    cardNumber: ADA.cardNumber,
    barcode: BOOK.barcode,
  });
});

test('lends the item and replies with its due date', () => {
  const store = sampleStore();
  const reply = handleCheckoutMessage(store, `11|AA${ADA.cardNumber}|AB${BOOK.barcode}|`, TODAY);
  assert.equal(reply, `121|AB${BOOK.id}|AH2026-12-17|`);
  assert.equal(store.findOpenLoan(BOOK.id).memberId, ADA.id);
});

test('refuses a card nobody holds', () => {
  const reply = handleCheckoutMessage(sampleStore(), `11|AA29999999999999|AB${BOOK.barcode}|`, TODAY);
  assert.equal(reply, '120|AFunknown-member|');
});

test('refuses a message that is not a checkout request', () => {
  assert.throws(() => parseCheckoutRequest('93|CNdesk|'), /Not a checkout request/);
});
// Days are calendar dates written as YYYY-MM-DD, read as UTC so that the server's time zone never
// shifts them.
const DAY_MS = 86_400_000;

function toTime(isoDate) {
  return Date.parse(`${isoDate}T00:00:00Z`);
}

/** Returns the calendar date `days` days after `isoDate`, or before it when `days` is negative. */
export function addDays(isoDate, days) {
  return new Date(toTime(isoDate) + days * DAY_MS).toISOString().slice(0, 10);
}

/** Returns how many days `later` is after `earlier`, negative when it is before. */
export function daysBetween(earlier, later) {
  return Math.round((toTime(later) - toTime(earlier)) / DAY_MS);
}

/** Returns the day of the week of a calendar date, 0 for Sunday to 6 for Saturday. */
export function weekdayOf(isoDate) {
  return new Date(toTime(isoDate)).getUTCDay();
}

/** Tells whether a branch is open on a calendar date. */
export function isOpenOn(branch, isoDate) {
  return !branch.closedWeekdays.includes(weekdayOf(isoDate));
}

/** Returns the first date on or after `isoDate` on which the branch is open. */
export function nextOpenDay(branch, isoDate) {
  let day = isoDate;
  while (!isOpenOn(branch, day)) day = addDays(day, 1);
  return day;
}
# lending-desk

The lending desk service of the city library's branches: checkouts, returns, renewals, holds, fees,
notices to members, and the self-check machines.

Plain Node.js ES modules, no dependencies. Node.js 22 or later.

```sh
npm test    # runs every test in test/
npm start   # serves the API on port 8080, with demo data
```

